CREATE TABLE `business_associates_questions` (
  `baq_id` int(11) NOT NULL AUTO_INCREMENT,
  `baq_title` text,
  `baq_text` text,
  `baq_order` int(11) DEFAULT NULL,
  `baq_active` tinyint(1) DEFAULT '1',
  `baq_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `baq_update_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`baq_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8;

/*Data for the table `business_associates_questions` */

insert  into `business_associates_questions`(`baq_id`,`baq_title`,`baq_text`,`baq_order`,`baq_active`,`baq_create_date`,`baq_update_date`) values (1,'Are your HIPAA policies and procedures up to date, effective and available?','<p style=\"border: 0;\">All covered entities should have organizational policies and procedures that address each requirement in the HIPAA Privacy and Security regulations. These HIPAA policies also need to address the changes outlined in the HITECH Act, enacted as part of ARRA. Further, when the final HITECH Act regulations were published in January 2013, HIPAA policies and procedures needed updating.</p>\r\n<p style=\"border: 0;\">Policies and Procedures need to be maintained in a “Master Manual” and be available for all employees, on an as needed basis.</p>\r\n<p style=\"border: 0;\">Organizations should also be monitoring employee compliance with HIPAA regulations to ensure that the policies and procedures in place effectively guide employees to correctly follow required HIPAA practices.</p>\r\n',1,1,'2014-05-15 22:32:08','0000-00-00 00:00:00'),(2,'Is your HIPAA training effective and up to date? How do you know?','<p style=\"border: 0;\">HIPAA requires all covered entities to deliver HIPAA training to its employees. These training presentations should be updated on a regularly basis to reflect regulatory or organizational changes.</p>\r\n<p style=\"border: 0;\">Additionally, organizations should have a system in place that evidence training completion, as well as procedures to ensure that trainings are delivered and attended in accordance with internal policies and procedures. Further, organizations should have evidence to substantiate that the trainings delivered are effective in providing employees with the information necessary to comply with HIPAA.</p>\r\n',2,1,'2014-05-15 22:33:01','0000-00-00 00:00:00'),(3,'Has a risk assessment been conducted? Did you follow the NIST SP800-30 protocol? Did you generate a Remediation Plan? Is the assessment and remediation plan updated regularly?','<p style=\"border: 0;\">The HIPAA Security Rule Administrative Safeguards provisions require covered entities to perform a risk assessment as part of their security management processes.   When analyzing potential risks to the security of PHI, organizations should (1) evaluate each risk’s likelihood and impact; (2) implement appropriate security measures to address identified risks; and (3) document the selected security measures, including an explanation of the reasoning for selection. Any corrective action taken by an organization as a result of the risk assessment findings should be monitored to completion and documented.  While not part of the Privacy Regulations, best practice is to conduct the same risk assessment on your privacy management processes.</p>\r\n<p style=\"border: 0;\">Once the Risk Assessment is completed, a remediation plan is required.  The remediation plan outlines a strategy to remediate the gaps in compliance identified during the Risk Assessment.  The plan should include for each identified threat, the risk score for the threat, the action to be taken to mitigate the threat, the individual responsible in mitigating the threat, and a  target date  for the threat to be mitigated.  Meaningful progress in implementing the mitigation plan is required for compliance.</p>\r\n<p style=\"border: 0;\">As risk assessment is an ongoing process, organizations should update their risk analysis, at least annually, to ensure that risks are appropriately identified, remediated and monitored.   Additionally, internal controls and security measures used should be regularly monitored and evaluated to ensure that PHI is appropriately and effectively protected.</p>\r\n',3,1,'2014-05-15 22:34:11','0000-00-00 00:00:00'),(4,'Do you have an ongoing auditing and monitoring programs for HIPAA Privacy and Security?','<p style=\"border: 0;\">Organizations should be monitoring its HIPAA Privacy and Security compliance on an ongoing basis.  Compliance Officers, in conjunction with the HIPAA Privacy and Security Officers, should be monitoring completion of HIPAA education, as well as detecting and investigating potential HIPAA incidents occurring during daily operations through the Hotline and any Human Resources and patient complaints. Additionally, there should be several HIPAA items included in the organization’s annual audit plan, specifically focusing on ensuring that patient records are accessed and disclosed appropriately and that internal controls are effectively securing PHI.</p>\r\n',4,1,'2014-05-15 22:34:12','0000-00-00 00:00:00'),(5,'Have you conducted due diligence on your sub-contractors?','<p style=\"border: 0;\">With the publication of the Final Omnibus Rules in January 2013, your relationship with your sub-contractors has fundamentally changed.  Before the Final Omnibus Rule, you had protection for civil liabilities, under HIPAA for a breach caused by a sub-contractor who conducts work for you under a Business Associate Agreement with a Covered Entity.  No more.  Now you can be held liable for breaches caused by your sub-contractors.</p>\r\n<p style=\"border: 0;\">You now have a requirement to investigate your sub-contractors to assure yourself that they are in fact complying with the same HIPAA requirements as you, and that there is not a pattern of behavior that has caused breaches in the past, or will likely cause a breach in the future.</p>\r\n',5,1,'2014-05-15 22:34:13','0000-00-00 00:00:00');
